import{_ as a,o as t,c as o,ag as r}from"./chunks/framework.cyF4XceO.js";const u=JSON.parse('{"title":"ContainerCustomDomain — takoform_container_custom_domain","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/container/container-custom-domain.md","filePath":"proposals/container/container-custom-domain.md"}'),i={name:"proposals/container/container-custom-domain.md"};function n(s,e,c,d,h,l){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="containercustomdomain-—-takoform-container-custom-domain" tabindex="-1">ContainerCustomDomain — <code>takoform_container_custom_domain</code> <a class="header-anchor" href="#containercustomdomain-—-takoform-container-custom-domain" aria-label="Permalink to &quot;ContainerCustomDomain — `takoform_container_custom_domain`&quot;">​</a></h1><blockquote><p>Historical/deferred candidate (English-only). This non-Edge Form is not in the current official Edge16 corpus or Current navigation.</p></blockquote><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>A team serves its container service on its own DNS hostname over HTTPS. External clients reach the service&#39;s active traffic split at that hostname; certificates and TLS termination are the host&#39;s obligation, never portable state.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>attachment</code>. Inward activation is an attachment resource, never a binding (decision 0010). Deleting the attachment detaches the hostname and never deletes the service.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p><code>hostname</code> is one dotted DNS name; <code>service</code> is the Container Service whose active traffic split answers it. Both are immutable: changing either replaces the attachment. Requests on the hostname are delivered to instances of the revisions the traffic resource selects, entirely one revision per request.</p><p>Certificate issuance is a host duty behind this attachment — <a href="./../../spec/decisions/0043-forms-target-popular-vendor-locked-primitives.html">decision 0043</a> records ACME as exactly that — and no certificate material, validation record, or issuer choice enters portable state.</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Hostname attachment is one complete observable fact: which name reaches which service. Certificate mechanics differ per host and are deliberately outside the contract.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>Path-pattern routing, multi-service routing under one hostname, and redirect or rewrite rules carry matching semantics beyond a whole hostname and are separate attachment Forms.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p>None.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None.</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>Two attachments claiming one hostname must conflict deterministically. They do: the hostname is canonicalized before it is compared and before it is stored, and one canonical hostname is claimed by at most one attachment per tenant, with <code>invalid_argument</code> (400) before any mutation (<a href="./../../spec/decisions/0026-attachment-claims-are-canonical-and-acyclic.html">decision 0026</a>). Attaching while the service has no traffic resource must be refused, per the family aggregate. Deleting the service while the attachment exists must fail with <code>dependency_in_use</code>. Import must recover hostname and service exactly.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The custom-domain mapping of a proven serverless container platform, with certificate provisioning kept host-side.</p>',21)])])}const p=a(i,[["render",n]]);export{u as __pageData,p as default};
